import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_17_three_tricks.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_17_twin_critics.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_17_delayed_update.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_17_target_smoothing.png",d="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_17_driving_boundary.png",P=JSON.parse('{"title":"评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险","description":"DDPG（深度确定性策略梯度）的演员会沿着评论家 Q 值上升的方向更新。这个机制在评论家准确时非常直接，在函数逼近存在误差时却很危险：演员并不知道哪里是真正的高回报，只知道哪里被评论家打了高分，于是会主动寻找并利用价值函数的错误尖峰。一次高估进入自举目标后，还可能沿时间不断传播。","frontmatter":{"title":"评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险","description":"DDPG（深度确定性策略梯度）的演员会沿着评论家 Q 值上升的方向更新。这个机制在评论家准确时非常直接，在函数逼近存在误差时却很危险：演员并不知道哪里是真正的高回报，只知道哪里被评论家打了高分，于是会主动寻找并利用价值函数的错误尖峰。一次高估进入自举目标后，还可能沿时间不断传播。","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":12,"source":"2026-08-13/rl_series_17_td3.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_17_three_tricks.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-17-td3"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险"}],["meta",{"property":"og:description","content":"DDPG（深度确定性策略梯度）的演员会沿着评论家 Q 值上升的方向更新。这个机制在评论家准确时非常直接，在函数逼近存在误差时却很危险：演员并不知道哪里是真正的高回报，只知道哪里被评论家打了高分，于是会主动寻找并利用价值函数的错误尖峰。一次高估进入自举目标后，还可能沿时间不断传播。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-17-td3"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_17_three_tricks.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险"}],["meta",{"name":"twitter:description","content":"DDPG（深度确定性策略梯度）的演员会沿着评论家 Q 值上升的方向更新。这个机制在评论家准确时非常直接，在函数逼近存在误差时却很危险：演员并不知道哪里是真正的高回报，只知道哪里被评论家打了高分，于是会主动寻找并利用价值函数的错误尖峰。一次高估进入自举目标后，还可能沿时间不断传播。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_17_three_tricks.png"}]],"prev":{"text":"连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进","link":"/rl/rl-series-16-ddpg"},"next":{"text":"不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了","link":"/rl/rl-series-18-sac"}},"headers":[],"relativePath":"rl/rl-series-17-td3.md","filePath":"rl/rl-series-17-td3.md","lastUpdated":null}'),s={name:"rl/rl-series-17-td3.md"};function c(p,a,_,u,b,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="评论家一高估-演员就钻空子-td3-怎样给-ddpg-加上三道保险" tabindex="-1">评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险 <a class="header-anchor" href="#评论家一高估-演员就钻空子-td3-怎样给-ddpg-加上三道保险" aria-label="Permalink to &quot;评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险&quot;">​</a></h1><p>DDPG（深度确定性策略梯度）的演员会沿着评论家 Q 值上升的方向更新。这个机制在评论家准确时非常直接，在函数逼近存在误差时却很危险：演员并不知道哪里是真正的高回报，只知道哪里被评论家打了高分，于是会主动寻找并利用价值函数的错误尖峰。一次高估进入自举目标后，还可能沿时间不断传播。</p><p>Twin Delayed Deep Deterministic Policy Gradient（双延迟深度确定性策略梯度，TD3）围绕这个耦合问题加入三项改造：Clipped Double Q-Learning（截断双 Q 学习）用两个评论家目标的较小值抑制高估；Delayed Policy Update（延迟策略更新）让评论家多学习、演员少移动；Target Policy Smoothing（目标策略平滑）在下一状态目标动作附近加受限噪声，降低策略利用狭窄 Q 峰值的机会。三项机制作用于不同位置，缺少任意一项都不再是完整 TD3。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-td3-不是简单地复制两个-ddpg" tabindex="-1">1.1 TD3 不是简单地复制两个 DDPG <a class="header-anchor" href="#_1-1-td3-不是简单地复制两个-ddpg" aria-label="Permalink to &quot;1.1 TD3 不是简单地复制两个 DDPG&quot;">​</a></h3><p>它只有一个主演员和一个目标演员，但拥有两个主评论家及对应目标评论家。两个评论家共同构造保守目标。</p><h3 id="_1-2-双评论家取较小值主要抑制高估" tabindex="-1">1.2 双评论家取较小值主要抑制高估 <a class="header-anchor" href="#_1-2-双评论家取较小值主要抑制高估" aria-label="Permalink to &quot;1.2 双评论家取较小值主要抑制高估&quot;">​</a></h3><p>目标使用两个目标 Q 值的最小值，而不是平均值。这样可能带来低估，却减少演员追逐虚假高值的风险。</p><h3 id="_1-3-延迟的是演员和目标网络更新" tabindex="-1">1.3 延迟的是演员和目标网络更新 <a class="header-anchor" href="#_1-3-延迟的是演员和目标网络更新" aria-label="Permalink to &quot;1.3 延迟的是演员和目标网络更新&quot;">​</a></h3><p>评论家通常每个梯度步更新，演员及软目标网络每隔若干评论家更新才执行一次，让策略在更稳定的价值地形上移动。</p><h3 id="_1-4-目标噪声与探索噪声职责不同" tabindex="-1">1.4 目标噪声与探索噪声职责不同 <a class="header-anchor" href="#_1-4-目标噪声与探索噪声职责不同" aria-label="Permalink to &quot;1.4 目标噪声与探索噪声职责不同&quot;">​</a></h3><p>探索噪声加入环境执行动作，改变收集的数据；目标策略噪声只用于评论家下一状态目标，作用是平滑价值估计。</p><p><img src="'+h+'" alt="TD3 用双评论家、延迟更新与目标平滑改造 DDPG"></p><h2 id="二、ddpg-的高估从哪里来" tabindex="-1">二、DDPG 的高估从哪里来 <a class="header-anchor" href="#二、ddpg-的高估从哪里来" aria-label="Permalink to &quot;二、DDPG 的高估从哪里来&quot;">​</a></h2><h3 id="_2-1-评论家不可避免地有近似误差" tabindex="-1">2.1 评论家不可避免地有近似误差 <a class="header-anchor" href="#_2-1-评论家不可避免地有近似误差" aria-label="Permalink to &quot;2.1 评论家不可避免地有近似误差&quot;">​</a></h3><p>有限网络、有限数据和随机目标都会让 (Q_\\phi(s,a)) 偏离真实价值。连续动作空间中，大量未充分采样的动作只能依赖外推。</p><h3 id="_2-2-演员承担隐式最大化角色" tabindex="-1">2.2 演员承担隐式最大化角色 <a class="header-anchor" href="#_2-2-演员承担隐式最大化角色" aria-label="Permalink to &quot;2.2 演员承担隐式最大化角色&quot;">​</a></h3><p>虽然 DDPG 没有显式写出 (\\max_a Q)，演员持续沿 Q 梯度寻找高值，相当于学习一个最大化器，也会偏好正向估计误差。</p><h3 id="_2-3-错误高值进入自举目标" tabindex="-1">2.3 错误高值进入自举目标 <a class="header-anchor" href="#_2-3-错误高值进入自举目标" aria-label="Permalink to &quot;2.3 错误高值进入自举目标&quot;">​</a></h3><p>目标评论家在下一状态动作上输出偏高价值，当前评论家将其当作标签拟合，误差随后传向更早状态。</p><h3 id="_2-4-演员与评论家形成正反馈" tabindex="-1">2.4 演员与评论家形成正反馈 <a class="header-anchor" href="#_2-4-演员与评论家形成正反馈" aria-label="Permalink to &quot;2.4 演员与评论家形成正反馈&quot;">​</a></h3><p>演员把数据分布推向评论家高估区域，评论家又缺少该区域的真实覆盖，错误可能被进一步放大。</p><h2 id="三、双评论家怎样形成保守目标" tabindex="-1">三、双评论家怎样形成保守目标 <a class="header-anchor" href="#三、双评论家怎样形成保守目标" aria-label="Permalink to &quot;三、双评论家怎样形成保守目标&quot;">​</a></h2><h3 id="_3-1-训练两个独立参数的-q-网络" tabindex="-1">3.1 训练两个独立参数的 Q 网络 <a class="header-anchor" href="#_3-1-训练两个独立参数的-q-网络" aria-label="Permalink to &quot;3.1 训练两个独立参数的 Q 网络&quot;">​</a></h3><p>主评论家写作 (Q_{\\phi_1}) 和 (Q_{\\phi_2})，它们使用相同样本和目标，却从不同初始化学习。</p><h3 id="_3-2-两个目标评论家分别估值" tabindex="-1">3.2 两个目标评论家分别估值 <a class="header-anchor" href="#_3-2-两个目标评论家分别估值" aria-label="Permalink to &quot;3.2 两个目标评论家分别估值&quot;">​</a></h3><p>给定目标动作 (A&#39;)，计算：</p><p>$$ Q_{1,targ}(S&#39;,A&#39;),\\qquad Q_{2,targ}(S&#39;,A&#39;) $$</p><h3 id="_3-3-目标取较小值" tabindex="-1">3.3 目标取较小值 <a class="header-anchor" href="#_3-3-目标取较小值" aria-label="Permalink to &quot;3.3 目标取较小值&quot;">​</a></h3><p>$$ Y=R+\\gamma(1-D)\\min_{i=1,2}Q_{\\phi_{i,targ}}(S&#39;,A&#39;) $$</p><p>两个主评论家都回归同一个保守目标。</p><h3 id="_3-4-取最小值不等于消除所有误差" tabindex="-1">3.4 取最小值不等于消除所有误差 <a class="header-anchor" href="#_3-4-取最小值不等于消除所有误差" aria-label="Permalink to &quot;3.4 取最小值不等于消除所有误差&quot;">​</a></h3><p>两个评论家共享数据和目标，误差可能相关。最小值会降低高估，也可能产生系统低估；它是经验性偏差控制，不是无偏保证。</p><p><img src="'+l+'" alt="TD3 使用两个目标评论家的较小值构造目标"></p><h2 id="四、为什么不用两个评论家的平均值" tabindex="-1">四、为什么不用两个评论家的平均值 <a class="header-anchor" href="#四、为什么不用两个评论家的平均值" aria-label="Permalink to &quot;四、为什么不用两个评论家的平均值&quot;">​</a></h2><h3 id="_4-1-平均值会保留正向误差" tabindex="-1">4.1 平均值会保留正向误差 <a class="header-anchor" href="#_4-1-平均值会保留正向误差" aria-label="Permalink to &quot;4.1 平均值会保留正向误差&quot;">​</a></h3><p>若一个评论家明显高估、另一个接近真实值，平均仍被高值拉升，演员仍可能受到错误激励。</p><h3 id="_4-2-最小值对高估更保守" tabindex="-1">4.2 最小值对高估更保守 <a class="header-anchor" href="#_4-2-最小值对高估更保守" aria-label="Permalink to &quot;4.2 最小值对高估更保守&quot;">​</a></h3><p>只要至少一个评论家没有同步高估，较小值就能压住目标。代价是任一评论家负向误差也会进入目标。</p><h3 id="_4-3-保守程度必须用真实回报核对" tabindex="-1">4.3 保守程度必须用真实回报核对 <a class="header-anchor" href="#_4-3-保守程度必须用真实回报核对" aria-label="Permalink to &quot;4.3 保守程度必须用真实回报核对&quot;">​</a></h3><p>Q 值变低本身不是成功。应比较预测 Q 与当前策略实现回报之间的差距，并观察策略性能是否提高。</p><h2 id="五、演员使用哪个评论家更新" tabindex="-1">五、演员使用哪个评论家更新 <a class="header-anchor" href="#五、演员使用哪个评论家更新" aria-label="Permalink to &quot;五、演员使用哪个评论家更新&quot;">​</a></h2><h3 id="_5-1-常见实现使用主评论家之一" tabindex="-1">5.1 常见实现使用主评论家之一 <a class="header-anchor" href="#_5-1-常见实现使用主评论家之一" aria-label="Permalink to &quot;5.1 常见实现使用主评论家之一&quot;">​</a></h3><p>演员损失通常为：</p><p>$$ L_\\mu(\\theta)=-\\mathbb E[Q_{\\phi_1}(S,\\mu_\\theta(S))] $$</p><p>不是对两个评论家最小值直接求演员梯度。</p><h3 id="_5-2-双评论家的主要作用在目标" tabindex="-1">5.2 双评论家的主要作用在目标 <a class="header-anchor" href="#_5-2-双评论家的主要作用在目标" aria-label="Permalink to &quot;5.2 双评论家的主要作用在目标&quot;">​</a></h3><p>保守最小值控制评论家自举标签，演员则沿一个主评论家的平滑梯度更新。具体实现需核对，不应从“twin”猜测所有位置都取最小值。</p><h3 id="_5-3-评论家参数在演员更新时冻结" tabindex="-1">5.3 评论家参数在演员更新时冻结 <a class="header-anchor" href="#_5-3-评论家参数在演员更新时冻结" aria-label="Permalink to &quot;5.3 评论家参数在演员更新时冻结&quot;">​</a></h3><p>仍需让梯度穿过 Q 对动作的导数，但不修改评论家权重，保持两类优化职责分离。</p><h2 id="六、延迟策略更新解决什么" tabindex="-1">六、延迟策略更新解决什么 <a class="header-anchor" href="#六、延迟策略更新解决什么" aria-label="Permalink to &quot;六、延迟策略更新解决什么&quot;">​</a></h2><h3 id="_6-1-评论家误差会立刻污染演员" tabindex="-1">6.1 评论家误差会立刻污染演员 <a class="header-anchor" href="#_6-1-评论家误差会立刻污染演员" aria-label="Permalink to &quot;6.1 评论家误差会立刻污染演员&quot;">​</a></h3><p>若每次评论家刚走一步就更新演员，价值估计尚未稳定，策略会不断追随短期噪声。</p><h3 id="_6-2-让评论家更新更频繁" tabindex="-1">6.2 让评论家更新更频繁 <a class="header-anchor" href="#_6-2-让评论家更新更频繁" aria-label="Permalink to &quot;6.2 让评论家更新更频繁&quot;">​</a></h3><p>TD3 常在每个训练步更新两个评论家，而每隔 <code>policy_delay</code> 个评论家步才更新演员。</p><h3 id="_6-3-目标网络与演员同步延迟" tabindex="-1">6.3 目标网络与演员同步延迟 <a class="header-anchor" href="#_6-3-目标网络与演员同步延迟" aria-label="Permalink to &quot;6.3 目标网络与演员同步延迟&quot;">​</a></h3><p>执行演员更新时，再软更新目标演员和两个目标评论家。这样目标网络的时间尺度与策略变化保持一致。</p><h3 id="_6-4-延迟不是等待评论家完全收敛" tabindex="-1">6.4 延迟不是等待评论家完全收敛 <a class="header-anchor" href="#_6-4-延迟不是等待评论家完全收敛" aria-label="Permalink to &quot;6.4 延迟不是等待评论家完全收敛&quot;">​</a></h3><p>深度评论家在非平稳数据上很难真正收敛。延迟只是降低每次策略变化之间累积的价值误差，并非严格两阶段优化。</p><p><img src="'+o+'" alt="评论家快更新，演员和目标网络慢更新"></p><h2 id="七、目标策略平滑怎样工作" tabindex="-1">七、目标策略平滑怎样工作 <a class="header-anchor" href="#七、目标策略平滑怎样工作" aria-label="Permalink to &quot;七、目标策略平滑怎样工作&quot;">​</a></h2><h3 id="_7-1-在目标演员动作上加入小噪声" tabindex="-1">7.1 在目标演员动作上加入小噪声 <a class="header-anchor" href="#_7-1-在目标演员动作上加入小噪声" aria-label="Permalink to &quot;7.1 在目标演员动作上加入小噪声&quot;">​</a></h3><p>$$ \\tilde A&#39;=\\operatorname{clip}\\left(\\mu_{\\theta_{targ}}(S&#39;)+\\epsilon,a_{low},a_{high}\\right) $$</p><p>其中 (\\epsilon) 来自零均值高斯分布，并先裁剪到有限范围。</p><h3 id="_7-2-评论家目标评价邻域动作" tabindex="-1">7.2 评论家目标评价邻域动作 <a class="header-anchor" href="#_7-2-评论家目标评价邻域动作" aria-label="Permalink to &quot;7.2 评论家目标评价邻域动作&quot;">​</a></h3><p>两个目标评论家在 (\\tilde A&#39;) 上计算价值。不同更新会采样略有差异的邻域动作，使目标近似关注动作附近的平均表现。</p><h3 id="_7-3-尖锐虚假峰值更难被利用" tabindex="-1">7.3 尖锐虚假峰值更难被利用 <a class="header-anchor" href="#_7-3-尖锐虚假峰值更难被利用" aria-label="Permalink to &quot;7.3 尖锐虚假峰值更难被利用&quot;">​</a></h3><p>如果只有一个极窄动作点被错误高估，邻域扰动后价值不再始终很高，演员难以仅靠命中尖峰获得持续目标收益。</p><h3 id="_7-4-噪声过大会模糊真实结构" tabindex="-1">7.4 噪声过大会模糊真实结构 <a class="header-anchor" href="#_7-4-噪声过大会模糊真实结构" aria-label="Permalink to &quot;7.4 噪声过大会模糊真实结构&quot;">​</a></h3><p>平滑尺度超过有效动作差异时，会把确实不同的控制效果混在一起，造成偏差。噪声标准差和裁剪值都需按归一化动作空间报告。</p><p><img src="'+n+'" alt="目标策略平滑用受限噪声削弱狭窄 Q 值尖峰"></p><h2 id="八、两种噪声为什么不能混淆" tabindex="-1">八、两种噪声为什么不能混淆 <a class="header-anchor" href="#八、两种噪声为什么不能混淆" aria-label="Permalink to &quot;八、两种噪声为什么不能混淆&quot;">​</a></h2><h3 id="_8-1-探索噪声作用于环境交互" tabindex="-1">8.1 探索噪声作用于环境交互 <a class="header-anchor" href="#_8-1-探索噪声作用于环境交互" aria-label="Permalink to &quot;8.1 探索噪声作用于环境交互&quot;">​</a></h3><p>主演员动作加探索噪声后送入环境，真实改变下一状态和回放缓冲区内容。</p><h3 id="_8-2-目标噪声只作用于训练标签" tabindex="-1">8.2 目标噪声只作用于训练标签 <a class="header-anchor" href="#_8-2-目标噪声只作用于训练标签" aria-label="Permalink to &quot;8.2 目标噪声只作用于训练标签&quot;">​</a></h3><p>它在从回放批次计算下一状态价值时临时生成，不送入环境，也不保存为历史动作。</p><h3 id="_8-3-评估时两种噪声都关闭" tabindex="-1">8.3 评估时两种噪声都关闭 <a class="header-anchor" href="#_8-3-评估时两种噪声都关闭" aria-label="Permalink to &quot;8.3 评估时两种噪声都关闭&quot;">​</a></h3><p>评估通常使用无噪主演员。若仍加入目标噪声，说明评估错误地执行了训练目标路径。</p><h3 id="_8-4-两者超参数不应共用一个名称" tabindex="-1">8.4 两者超参数不应共用一个名称 <a class="header-anchor" href="#_8-4-两者超参数不应共用一个名称" aria-label="Permalink to &quot;8.4 两者超参数不应共用一个名称&quot;">​</a></h3><p>配置应区分 <code>exploration_noise_std</code>、<code>target_noise_std</code> 和 <code>target_noise_clip</code>，避免调参时改错数据流。</p><h2 id="九、完整-td3-更新怎样串起来" tabindex="-1">九、完整 TD3 更新怎样串起来 <a class="header-anchor" href="#九、完整-td3-更新怎样串起来" aria-label="Permalink to &quot;九、完整 TD3 更新怎样串起来&quot;">​</a></h2><h3 id="_9-1-从回放池抽取批次" tabindex="-1">9.1 从回放池抽取批次 <a class="header-anchor" href="#_9-1-从回放池抽取批次" aria-label="Permalink to &quot;9.1 从回放池抽取批次&quot;">​</a></h3><p>获得状态、真实执行动作、奖励、下一状态和自然终止标记。</p><h3 id="_9-2-目标演员生成平滑动作" tabindex="-1">9.2 目标演员生成平滑动作 <a class="header-anchor" href="#_9-2-目标演员生成平滑动作" aria-label="Permalink to &quot;9.2 目标演员生成平滑动作&quot;">​</a></h3><p>对目标动作加入裁剪高斯噪声，再裁剪到合法动作范围。</p><h3 id="_9-3-双目标评论家取较小值" tabindex="-1">9.3 双目标评论家取较小值 <a class="header-anchor" href="#_9-3-双目标评论家取较小值" aria-label="Permalink to &quot;9.3 双目标评论家取较小值&quot;">​</a></h3><p>构造保守 Bellman 目标，并同时更新两个主评论家。</p><h3 id="_9-4-按延迟周期更新演员" tabindex="-1">9.4 按延迟周期更新演员 <a class="header-anchor" href="#_9-4-按延迟周期更新演员" aria-label="Permalink to &quot;9.4 按延迟周期更新演员&quot;">​</a></h3><p>使用主评论家之一评价主演员动作，更新确定性策略。</p><h3 id="_9-5-同步软更新三个目标模块" tabindex="-1">9.5 同步软更新三个目标模块 <a class="header-anchor" href="#_9-5-同步软更新三个目标模块" aria-label="Permalink to &quot;9.5 同步软更新三个目标模块&quot;">​</a></h3><p>更新目标演员和两个目标评论家，然后继续下一个评论家训练步。</p><h2 id="十、三项技巧怎样相互配合" tabindex="-1">十、三项技巧怎样相互配合 <a class="header-anchor" href="#十、三项技巧怎样相互配合" aria-label="Permalink to &quot;十、三项技巧怎样相互配合&quot;">​</a></h2><h3 id="_10-1-双评论家降低目标高估" tabindex="-1">10.1 双评论家降低目标高估 <a class="header-anchor" href="#_10-1-双评论家降低目标高估" aria-label="Permalink to &quot;10.1 双评论家降低目标高估&quot;">​</a></h3><p>它改变自举目标数值，抑制偏高标签传播。</p><h3 id="_10-2-策略延迟减少错误放大频率" tabindex="-1">10.2 策略延迟减少错误放大频率 <a class="header-anchor" href="#_10-2-策略延迟减少错误放大频率" aria-label="Permalink to &quot;10.2 策略延迟减少错误放大频率&quot;">​</a></h3><p>它改变更新时序，让演员少追逐评论家瞬时噪声。</p><h3 id="_10-3-目标平滑降低动作方向脆弱性" tabindex="-1">10.3 目标平滑降低动作方向脆弱性 <a class="header-anchor" href="#_10-3-目标平滑降低动作方向脆弱性" aria-label="Permalink to &quot;10.3 目标平滑降低动作方向脆弱性&quot;">​</a></h3><p>它改变目标动作分布，让评论家难以依赖极窄高峰。</p><h3 id="_10-4-组合收益需要消融验证" tabindex="-1">10.4 组合收益需要消融验证 <a class="header-anchor" href="#_10-4-组合收益需要消融验证" aria-label="Permalink to &quot;10.4 组合收益需要消融验证&quot;">​</a></h3><p>不同任务可能由不同误差主导。应分别移除每项机制并保持其他预算一致，避免把所有提升归给“twin”。</p><h2 id="十一、td3-仍然有哪些局限" tabindex="-1">十一、TD3 仍然有哪些局限 <a class="header-anchor" href="#十一、td3-仍然有哪些局限" aria-label="Permalink to &quot;十一、TD3 仍然有哪些局限&quot;">​</a></h2><h3 id="_11-1-策略仍是确定性的" tabindex="-1">11.1 策略仍是确定性的 <a class="header-anchor" href="#_11-1-策略仍是确定性的" aria-label="Permalink to &quot;11.1 策略仍是确定性的&quot;">​</a></h3><p>训练探索依赖外加噪声，无法像随机策略那样直接表示动作不确定性或多模态行为。</p><h3 id="_11-2-最小值可能造成低估" tabindex="-1">11.2 最小值可能造成低估 <a class="header-anchor" href="#_11-2-最小值可能造成低估" aria-label="Permalink to &quot;11.2 最小值可能造成低估&quot;">​</a></h3><p>保守目标减轻高估，却可能让价值过低、演员更新过于谨慎，尤其当某个评论家长期质量较差时。</p><h3 id="_11-3-回放分布外推仍然存在" tabindex="-1">11.3 回放分布外推仍然存在 <a class="header-anchor" href="#_11-3-回放分布外推仍然存在" aria-label="Permalink to &quot;11.3 回放分布外推仍然存在&quot;">​</a></h3><p>双评论家都可能在缺少数据的动作区域犯相似错误。取最小值不能替代覆盖和分布外检测。</p><h3 id="_11-4-超参数依然相互耦合" tabindex="-1">11.4 超参数依然相互耦合 <a class="header-anchor" href="#_11-4-超参数依然相互耦合" aria-label="Permalink to &quot;11.4 超参数依然相互耦合&quot;">​</a></h3><p>策略延迟、软更新、目标噪声、探索噪声和更新数据比共同决定训练行为，不是默认值在所有任务上通用。</p><h2 id="十二、如何诊断双评论家" tabindex="-1">十二、如何诊断双评论家 <a class="header-anchor" href="#十二、如何诊断双评论家" aria-label="Permalink to &quot;十二、如何诊断双评论家&quot;">​</a></h2><h3 id="_12-1-记录两个-q-值及其差值" tabindex="-1">12.1 记录两个 Q 值及其差值 <a class="header-anchor" href="#_12-1-记录两个-q-值及其差值" aria-label="Permalink to &quot;12.1 记录两个 Q 值及其差值&quot;">​</a></h3><p>若两个评论家长期完全相同，可能初始化、参数或优化器被意外共享；若差异持续巨大，说明至少一个评论家不稳定。</p><h3 id="_12-2-比较最小值与实现回报" tabindex="-1">12.2 比较最小值与实现回报 <a class="header-anchor" href="#_12-2-比较最小值与实现回报" aria-label="Permalink to &quot;12.2 比较最小值与实现回报&quot;">​</a></h3><p>固定评估状态动作，通过多次 Rollout（展开轨迹）估计真实回报，检查最小值是更准确还是过度低估。</p><h3 id="_12-3-观察演员动作处的局部曲线" tabindex="-1">12.3 观察演员动作处的局部曲线 <a class="header-anchor" href="#_12-3-观察演员动作处的局部曲线" aria-label="Permalink to &quot;12.3 观察演员动作处的局部曲线&quot;">​</a></h3><p>在动作邻域做小扰动，绘制两个评论家价值。极窄峰值、剧烈不一致或动作边界异常都是风险信号。</p><h3 id="_12-4-监控延迟更新计数" tabindex="-1">12.4 监控延迟更新计数 <a class="header-anchor" href="#_12-4-监控延迟更新计数" aria-label="Permalink to &quot;12.4 监控延迟更新计数&quot;">​</a></h3><p>确认演员和目标网络按评论家梯度步计数，而不是误用环境步或回合数。训练频率改变后计数语义必须保持明确。</p><h2 id="十三、训练预算怎样公平比较" tabindex="-1">十三、训练预算怎样公平比较 <a class="header-anchor" href="#十三、训练预算怎样公平比较" aria-label="Permalink to &quot;十三、训练预算怎样公平比较&quot;">​</a></h2><h3 id="_13-1-同时报告环境步和梯度步" tabindex="-1">13.1 同时报告环境步和梯度步 <a class="header-anchor" href="#_13-1-同时报告环境步和梯度步" aria-label="Permalink to &quot;13.1 同时报告环境步和梯度步&quot;">​</a></h3><p>TD3 可能每个环境步执行多个评论家更新，单看环境步无法反映计算预算。</p><h3 id="_13-2-双评论家增加计算量" tabindex="-1">13.2 双评论家增加计算量 <a class="header-anchor" href="#_13-2-双评论家增加计算量" aria-label="Permalink to &quot;13.2 双评论家增加计算量&quot;">​</a></h3><p>与 DDPG 对比时，TD3 每步评论家前向和反向约翻倍。性能提升需结合墙钟时间、显存与样本效率解释。</p><h3 id="_13-3-使用相同评估协议和多种子" tabindex="-1">13.3 使用相同评估协议和多种子 <a class="header-anchor" href="#_13-3-使用相同评估协议和多种子" aria-label="Permalink to &quot;13.3 使用相同评估协议和多种子&quot;">​</a></h3><p>关闭探索噪声，固定评估频率和回合数，报告失败运行。原论文与不同实现之间的结果也可能受调参和代码细节影响。</p><h2 id="十四、自动驾驶中-td3-的边界" tabindex="-1">十四、自动驾驶中 TD3 的边界 <a class="header-anchor" href="#十四、自动驾驶中-td3-的边界" aria-label="Permalink to &quot;十四、自动驾驶中 TD3 的边界&quot;">​</a></h2><h3 id="_14-1-平滑目标符合局部鲁棒直觉" tabindex="-1">14.1 平滑目标符合局部鲁棒直觉 <a class="header-anchor" href="#_14-1-平滑目标符合局部鲁棒直觉" aria-label="Permalink to &quot;14.1 平滑目标符合局部鲁棒直觉&quot;">​</a></h3><p>真实执行存在误差，若策略只在精确动作点得到高价值，部署会很脆弱。目标平滑鼓励动作邻域具有相近价值。</p><h3 id="_14-2-平滑不等于动力学鲁棒保证" tabindex="-1">14.2 平滑不等于动力学鲁棒保证 <a class="header-anchor" href="#_14-2-平滑不等于动力学鲁棒保证" aria-label="Permalink to &quot;14.2 平滑不等于动力学鲁棒保证&quot;">​</a></h3><p>训练噪声只在动作标签附近取样，没有证明闭环系统对模型误差、时延和扰动稳定。</p><h3 id="_14-3-双评论家不是风险上下界" tabindex="-1">14.3 双评论家不是风险上下界 <a class="header-anchor" href="#_14-3-双评论家不是风险上下界" aria-label="Permalink to &quot;14.3 双评论家不是风险上下界&quot;">​</a></h3><p>两个近似网络的最小值不是统计置信下界，也不能直接解释成碰撞风险保守估计。</p><h3 id="_14-4-安全层仍需验证真实动作" tabindex="-1">14.4 安全层仍需验证真实动作 <a class="header-anchor" href="#_14-4-安全层仍需验证真实动作" aria-label="Permalink to &quot;14.4 安全层仍需验证真实动作&quot;">​</a></h3><p>演员输出经过限幅、速率限制和安全屏蔽后才执行，回放必须保存真实执行动作并记录介入。</p><p><img src="'+d+'" alt="TD3 的价值保守机制不能替代车辆安全约束"></p><h2 id="十五、一个最小实验怎样设计" tabindex="-1">十五、一个最小实验怎样设计 <a class="header-anchor" href="#十五、一个最小实验怎样设计" aria-label="Permalink to &quot;十五、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_15-1-先复现稳定-ddpg-基线" tabindex="-1">15.1 先复现稳定 DDPG 基线 <a class="header-anchor" href="#_15-1-先复现稳定-ddpg-基线" aria-label="Permalink to &quot;15.1 先复现稳定 DDPG 基线&quot;">​</a></h3><p>若基线终止语义、动作缩放或目标网络有错，TD3 的比较没有意义。先用多个种子确认 DDPG 的波动范围。</p><h3 id="_15-2-逐项加入三项机制" tabindex="-1">15.2 逐项加入三项机制 <a class="header-anchor" href="#_15-2-逐项加入三项机制" aria-label="Permalink to &quot;15.2 逐项加入三项机制&quot;">​</a></h3><p>分别测试双评论家、策略延迟和目标平滑，再测试完整组合，保持环境步、梯度预算和网络容量记录清楚。</p><h3 id="_15-3-增加-q-值校准指标" tabindex="-1">15.3 增加 Q 值校准指标 <a class="header-anchor" href="#_15-3-增加-q-值校准指标" aria-label="Permalink to &quot;15.3 增加 Q 值校准指标&quot;">​</a></h3><p>除回报外，报告两个评论家预测、最小值、实现回报差距和局部动作扰动曲线，验证机制是否真的抑制高估。</p><h2 id="十六、最常见的实现错误" tabindex="-1">十六、最常见的实现错误 <a class="header-anchor" href="#十六、最常见的实现错误" aria-label="Permalink to &quot;十六、最常见的实现错误&quot;">​</a></h2><h3 id="_16-1-两个评论家意外共享参数" tabindex="-1">16.1 两个评论家意外共享参数 <a class="header-anchor" href="#_16-1-两个评论家意外共享参数" aria-label="Permalink to &quot;16.1 两个评论家意外共享参数&quot;">​</a></h3><p>若复制的是引用而不是独立实例，所谓双评论家只是一张网络计算两次，无法形成估计差异。</p><h3 id="_16-2-取了主评论家而不是目标评论家的最小值" tabindex="-1">16.2 取了主评论家而不是目标评论家的最小值 <a class="header-anchor" href="#_16-2-取了主评论家而不是目标评论家的最小值" aria-label="Permalink to &quot;16.2 取了主评论家而不是目标评论家的最小值&quot;">​</a></h3><p>Bellman 目标应使用两个目标评论家。主评论家负责当前预测和优化。</p><h3 id="_16-3-目标噪声没有双重裁剪" tabindex="-1">16.3 目标噪声没有双重裁剪 <a class="header-anchor" href="#_16-3-目标噪声没有双重裁剪" aria-label="Permalink to &quot;16.3 目标噪声没有双重裁剪&quot;">​</a></h3><p>先裁剪噪声幅度，再将扰动后的目标动作裁剪到环境合法范围，缺少任一步都可能产生异常目标。</p><h3 id="_16-4-每步都更新演员和目标网络" tabindex="-1">16.4 每步都更新演员和目标网络 <a class="header-anchor" href="#_16-4-每步都更新演员和目标网络" aria-label="Permalink to &quot;16.4 每步都更新演员和目标网络&quot;">​</a></h3><p>这样会丢失“delayed”的核心。需要显式测试计数器和更新次数。</p><h3 id="_16-5-把评论家最小值用于所有位置" tabindex="-1">16.5 把评论家最小值用于所有位置 <a class="header-anchor" href="#_16-5-把评论家最小值用于所有位置" aria-label="Permalink to &quot;16.5 把评论家最小值用于所有位置&quot;">​</a></h3><p>目标处取最小值，演员通常沿第一个主评论家更新。机械地到处取最小值会改变算法。</p><h2 id="十七、学到什么程度才算掌握" tabindex="-1">十七、学到什么程度才算掌握 <a class="header-anchor" href="#十七、学到什么程度才算掌握" aria-label="Permalink to &quot;十七、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_17-1-能把三项改造映射到三个问题" tabindex="-1">17.1 能把三项改造映射到三个问题 <a class="header-anchor" href="#_17-1-能把三项改造映射到三个问题" aria-label="Permalink to &quot;17.1 能把三项改造映射到三个问题&quot;">​</a></h3><p>双评论家处理高估，延迟更新处理演员—评论家时间耦合，目标平滑处理动作方向尖峰。</p><h3 id="_17-2-能区分网络数量与更新时序" tabindex="-1">17.2 能区分网络数量与更新时序 <a class="header-anchor" href="#_17-2-能区分网络数量与更新时序" aria-label="Permalink to &quot;17.2 能区分网络数量与更新时序&quot;">​</a></h3><p>一个演员、两个评论家以及对应目标网络何时更新、由哪个损失驱动，都应能准确画出。</p><h3 id="_17-3-能解释保守并不等于安全" tabindex="-1">17.3 能解释保守并不等于安全 <a class="header-anchor" href="#_17-3-能解释保守并不等于安全" aria-label="Permalink to &quot;17.3 能解释保守并不等于安全&quot;">​</a></h3><p>较低 Q 目标只是价值估计策略，不是物理风险界，也不替代安全验证。</p><h3 id="_17-4-能准备进入-sac" tabindex="-1">17.4 能准备进入 SAC <a class="header-anchor" href="#_17-4-能准备进入-sac" aria-label="Permalink to &quot;17.4 能准备进入 SAC&quot;">​</a></h3><p>下一篇将保留异策略回放与双评论家，但把确定性演员换成随机策略，并把熵直接写入价值目标与策略目标。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter12/chapter12.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十二章 TD3 部分</a></p><p><a href="https://proceedings.mlr.press/v80/fujimoto18a.html" target="_blank" rel="noreferrer">Fujimoto 等《Addressing Function Approximation Error in Actor-Critic Methods》</a></p><p><a href="https://spinningup.openai.com/en/latest/algorithms/td3.html" target="_blank" rel="noreferrer">OpenAI Spinning Up TD3 文档</a></p><p><a href="https://github.com/sfujim/TD3" target="_blank" rel="noreferrer">TD3 作者参考实现</a></p>',167)])])}const f=e(s,[["render",c]]);export{P as __pageData,f as default};
